<?php require_once __DIR__.'/../config/db.php';require_login();$pdo=db();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)$_POST['id_producto'];$tipo=$_POST['tipo_movimiento'];$cantidad=(int)$_POST['cantidad'];$obs=trim($_POST['observacion']??'');try{$pdo->beginTransaction();$s=$pdo->prepare('SELECT cantidad FROM productos WHERE id_producto=? FOR UPDATE');$s->execute([$id]);$p=$s->fetch();if(!$p)throw new Exception('Producto no encontrado.');if($cantidad<=0)throw new Exception('La cantidad debe ser mayor que cero.');$nueva=$tipo==='entrada'?$p['cantidad']+$cantidad:$p['cantidad']-$cantidad;if($nueva<0)throw new Exception('No hay existencias suficientes para realizar la salida.');$s=$pdo->prepare('UPDATE productos SET cantidad=? WHERE id_producto=?');$s->execute([$nueva,$id]);$s=$pdo->prepare('INSERT INTO movimientos_inventario(id_producto,id_usuario,tipo_movimiento,cantidad,fecha,observacion) VALUES(?,?,?,?,NOW(),?)');$s->execute([$id,$_SESSION['user']['id_usuario'],$tipo,$cantidad,$obs]);$pdo->commit();header('Location: movimientos.php');exit;}catch(Exception $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}$productos=$pdo->query('SELECT id_producto,nombre,cantidad FROM productos ORDER BY nombre')->fetchAll();$rows=$pdo->query('SELECT m.*,p.nombre producto,u.nombre usuario FROM movimientos_inventario m JOIN productos p ON p.id_producto=m.id_producto JOIN usuarios u ON u.id_usuario=m.id_usuario ORDER BY m.fecha DESC LIMIT 100')->fetchAll();$title='Movimientos';require 'header.php';?><h2>Movimientos de inventario</h2><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="card mb-4"><div class="card-body"><form method="post" class="row g-2"><div class="col-md-4"><select class="form-select" name="id_producto" required><option value="">Producto</option><?php foreach($productos as $p):?><option value="<?=$p['id_producto']?>"><?=e($p['nombre'])?> (stock <?=$p['cantidad']?>)</option><?php endforeach;?></select></div><div class="col-md-2"><select class="form-select" name="tipo_movimiento"><option value="entrada">Entrada</option><option value="salida">Salida</option></select></div><div class="col-md-2"><input class="form-control" type="number" min="1" name="cantidad" placeholder="Cantidad" required></div><div class="col-md-3"><input class="form-control" name="observacion" placeholder="Observación"></div><div class="col-md-1"><button class="btn btn-primary w-100">Registrar</button></div></form></div></div><div class="card"><div class="card-body"><div class="table-responsive"><table class="table"><thead><tr><th>Fecha</th><th>Producto</th><th>Tipo</th><th>Cantidad</th><th>Usuario</th><th>Observación</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['fecha'])?></td><td><?=e($r['producto'])?></td><td><span class="badge <?=$r['tipo_movimiento']==='entrada'?'text-bg-success':'text-bg-danger'?>"><?=e($r['tipo_movimiento'])?></span></td><td><?=$r['cantidad']?></td><td><?=e($r['usuario'])?></td><td><?=e($r['observacion'])?></td></tr><?php endforeach;?></tbody></table></div></div></div><?php require 'footer.php';
